#[derive(Debug, Clone, Default)]
struct ReindexVectorTarget {
    drawer_ids: Vec<String>,
    project_id: Option<String>,
    wing: Option<String>,
    room: Option<String>,
    limit: Option<usize>,
}

impl ReindexVectorTarget {
    fn is_empty(&self) -> bool {
        self.drawer_ids.is_empty()
            && self.project_id.is_none()
            && self.wing.is_none()
            && self.room.is_none()
            && self.limit.is_none()
    }

    fn has_scope_filter(&self) -> bool {
        !self.drawer_ids.is_empty()
            || self.project_id.is_some()
            || self.wing.is_some()
            || self.room.is_some()
    }
}

struct RollbackCommandOptions<'a> {
    since: &'a str,
    wing: Option<&'a str>,
    room: Option<&'a str>,
    project: Option<&'a str>,
    dry_run: bool,
    json: bool,
}

fn resolve_room_session_scope(room: Option<&str>, session: Option<&str>) -> Result<Option<String>> {
    match (room, session) {
        (Some(room), Some(session)) if room != session => {
            bail!("--session conflicts with --room; session maps to the drawer room column")
        }
        (Some(room), _) => Ok(Some(room.to_string())),
        (None, Some(session)) => Ok(Some(session.to_string())),
        (None, None) => Ok(None),
    }
}

