#[derive(Subcommand)]
enum OperationCommands {
    /// Print the current status of a receipt-backed ingest operation.
    Status {
        operation_id: String,
        #[arg(long)]
        json: bool,
    },
    /// Block until a receipt-backed ingest operation reaches a terminal state.
    Wait {
        operation_id: String,
        #[arg(long = "timeout-secs", default_value_t = 30)]
        timeout_secs: u64,
        #[arg(long)]
        json: bool,
    },
}

#[derive(Subcommand)]
enum DoctorCommands {
    /// Diagnose REST feature, endpoint readiness, routes, and port ownership.
    Rest {
        /// REST endpoint or host:port to probe. Defaults to config api.addr.
        #[arg(long)]
        addr: Option<String>,
        #[arg(long, default_value = "plain")]
        format: String,
    },
}

#[derive(Subcommand)]
enum ExportCommands {
    /// Export active drawers as generated Markdown mirror files.
    #[command(
        long_about = "Export active drawers from canonical SQLite into deterministic Markdown mirror files.\n\nSQLite remains the source of truth. Markdown files are generated review/export artifacts, not the canonical store. Non-empty unmanaged directories are refused; existing mempal mirrors are refreshed through their manifest, and colliding unmanaged files stop the export. Import/watch sync is intentionally not active in this command; any future import/watch path must be explicit opt-in and conflict-safe."
    )]
    Md {
        /// Directory that will receive generated Markdown files.
        output_dir: PathBuf,
        /// Export only this project ID. Defaults to the configured/current project when available.
        #[arg(long)]
        project: Option<String>,
        /// Include legacy global drawers together with --project/current project.
        #[arg(long, default_value_t = false)]
        include_global: bool,
        /// Export all active drawers across project scopes.
        #[arg(long, default_value_t = false)]
        all_projects: bool,
        /// Restrict export to one wing.
        #[arg(long)]
        wing: Option<String>,
        /// Restrict export to one room.
        #[arg(long)]
        room: Option<String>,
        /// Maximum bytes of redacted body content written per drawer.
        #[arg(long = "max-body-bytes", default_value_t = default_max_body_bytes())]
        max_body_bytes: usize,
        /// Disable export-boundary redaction. By default, secret-like values are redacted.
        #[arg(long, default_value_t = false)]
        no_redact: bool,
    },
}

#[derive(Subcommand)]
enum WikiCommands {
    /// Build source-backed Markdown wiki pages from canonical SQLite memory.
    #[command(
        long_about = "Build deterministic Markdown wiki pages for entities and decisions from canonical SQLite memory.\n\nThe wiki is a derived read-only view, not a second source of truth. Generated pages include drawer/triple citations, separate active and superseded claims, redact secret-like values by default, and write a .mempal-wiki.toml manifest for later verification."
    )]
    Build {
        /// Directory that will receive generated wiki pages.
        output_dir: PathBuf,
        /// Build only this project ID. Defaults to the configured/current project when available.
        #[arg(long)]
        project: Option<String>,
        /// Include legacy global drawers together with --project/current project.
        #[arg(long, default_value_t = false)]
        include_global: bool,
        /// Build pages across all project scopes.
        #[arg(long, default_value_t = false)]
        all_projects: bool,
        /// Unix seconds or RFC3339 timestamp used to classify expired claims.
        #[arg(long)]
        now: Option<String>,
        /// Disable wiki Markdown redaction. By default, secret-like values are redacted.
        #[arg(long, default_value_t = false)]
        no_redact: bool,
    },
    /// Verify generated wiki pages against current SQLite refs without editing pages.
    #[command(
        long_about = "Verify a generated mempal knowledge wiki against canonical SQLite memory.\n\nThis mode checks the manifest's drawer/triple fingerprints and flags pages whose supporting refs changed, disappeared, were deleted, or expired. It never treats Markdown as authoritative input."
    )]
    Verify {
        /// Directory containing a .mempal-wiki.toml manifest.
        output_dir: PathBuf,
        /// Unix seconds or RFC3339 timestamp used to classify expired refs.
        #[arg(long)]
        now: Option<String>,
    },
}

#[derive(Subcommand)]
enum CheckpointCommands {
    /// Save a session checkpoint drawer.
    Save {
        /// Explicit content. Reads from stdin if omitted.
        #[arg(long)]
        content: Option<String>,
        /// Project ID override.
        #[arg(long)]
        project: Option<String>,
    },
    /// Retrieve the latest checkpoint content.
    Latest {
        /// Project ID filter.
        #[arg(long)]
        project: Option<String>,
        /// Output as JSON.
        #[arg(long)]
        json: bool,
    },
    /// Soft-delete checkpoints older than a given age.
    Cleanup {
        /// Max age to keep (e.g. '24h', '7d'). Default: 24h.
        #[arg(long, default_value = "24h")]
        max_age: String,
        /// Show what would be deleted without doing it.
        #[arg(long)]
        dry_run: bool,
    },
    /// Extract session context from a Claude Code session JSONL file.
    Extract {
        /// Path to the session JSONL file.
        path: PathBuf,
        /// Only show the last N assistant messages. Default: 1.
        #[arg(long, default_value_t = 1)]
        last: usize,
    },
    /// Enable automatic checkpoint on Stop hook.
    Enable,
    /// Disable automatic checkpoint on Stop hook.
    Disable,
    /// Show whether automatic checkpoint is enabled or disabled.
    Status,
}

#[derive(Subcommand)]
enum XurlCommands {
    /// Ingest turns from a single file or scan all default tool directories.
    Ingest {
        /// Tool source: cc, codex, or hermes. Required when --path is given.
        #[arg(long, value_enum)]
        tool: Option<XurlTool>,
        /// Path to a specific file to ingest. Omit to scan default directories.
        #[arg(long)]
        path: Option<PathBuf>,
        /// Override session ID (only used with --path).
        #[arg(long)]
        session_id: Option<String>,
        /// Print result as JSON.
        #[arg(long)]
        json: bool,
    },
    /// Semantic search over indexed conversation turns.
    Search {
        /// Search query string.
        query: String,
        /// Filter by tool: cc, codex, or hermes.
        #[arg(long, value_enum)]
        tool: Option<XurlTool>,
        /// Filter to a specific session ID.
        #[arg(long)]
        session: Option<String>,
        /// Only return turns newer than this duration (e.g. 7d, 24h, 10m).
        #[arg(long)]
        since: Option<String>,
        /// Maximum number of results to return.
        #[arg(long, default_value_t = 10)]
        limit: usize,
        /// Page number (0-based).
        #[arg(long, default_value_t = 0)]
        page: usize,
        /// Also include CSA-delegated turns (excluded by default).
        #[arg(long)]
        include_csa: bool,
        /// Also include agent-generated user prompts (excluded by default).
        #[arg(long)]
        include_agent_prompts: bool,
        /// Minimum cosine similarity score (0.0–1.0). Hits below this floor are suppressed.
        #[arg(long, default_value_t = 0.70)]
        min_score: f32,
        /// Output format: markdown (default) or json.
        #[arg(long, value_enum, default_value_t = XurlFormat::Markdown)]
        format: XurlFormat,
    },
    /// Show conversation turns in reverse-chronological order.
    Timeline {
        /// Filter by tool: cc, codex, or hermes.
        #[arg(long, value_enum)]
        tool: Option<XurlTool>,
        /// Filter to a specific session ID.
        #[arg(long)]
        session: Option<String>,
        /// Only return turns newer than this duration (e.g. 7d, 24h, 10m).
        #[arg(long)]
        since: Option<String>,
        /// Number of turns per page.
        #[arg(long, default_value_t = 20)]
        limit: usize,
        /// Page number (0-based).
        #[arg(long, default_value_t = 0)]
        page: usize,
        /// Also include CSA-delegated turns (excluded by default).
        #[arg(long)]
        include_csa: bool,
        /// Also include agent-generated user prompts (excluded by default).
        #[arg(long)]
        include_agent_prompts: bool,
        /// Output format: markdown (default) or json.
        #[arg(long, value_enum, default_value_t = XurlFormat::Markdown)]
        format: XurlFormat,
    },
    /// Show per-tool turn counts and date ranges.
    Stats {
        /// Filter by tool: cc, codex, or hermes.
        #[arg(long, value_enum)]
        tool: Option<XurlTool>,
        /// Filter to a specific session ID.
        #[arg(long)]
        session: Option<String>,
        /// Only include turns newer than this duration (e.g. 7d, 24h, 10m).
        #[arg(long)]
        since: Option<String>,
        /// Print result as JSON.
        #[arg(long)]
        json: bool,
    },
    /// Embed all turns that still lack a vector (drains the historical backlog).
    Reindex {
        /// Re-embed only turns whose vector metadata is missing or stale.
        #[arg(long)]
        stale: bool,
        /// Rebuild vectors for all turns.
        #[arg(long)]
        force: bool,
        /// Show how many threads/turns would be embedded without writing vectors.
        #[arg(long)]
        dry_run: bool,
        /// Print progress as JSON.
        #[arg(long)]
        json: bool,
    },
    /// Backfill project_path for historical turns without re-ingesting content.
    Backfill {
        /// Show what would be updated without writing.
        #[arg(long)]
        dry_run: bool,
        /// Print result as JSON.
        #[arg(long)]
        json: bool,
    },
}

#[derive(Clone, Copy, clap::ValueEnum)]
enum XurlTool {
    Cc,
    Codex,
    Hermes,
}

#[derive(Debug, Clone, Copy, clap::ValueEnum)]
enum XurlFormat {
    Markdown,
    Json,
}

#[derive(Subcommand)]
enum HermesCommands {
    /// Ingest Hermes state.db or a Hermes JSONL export.
    Ingest(HermesIngestArgs),
    /// Semantic search over indexed Hermes turns.
    Search(HermesQueryArgs),
    /// Alias for search with recall-oriented flags.
    Recall(HermesQueryArgs),
}

#[derive(Subcommand)]
enum RecallCommands {
    /// Semantic recall over indexed Hermes turns.
    Hermes(HermesQueryArgs),
}

#[derive(Debug, Clone, Args)]
struct HermesIngestArgs {
    /// Hermes profile name. `default` maps to ~/.hermes/state.db.
    #[arg(long, default_value = "default")]
    profile: String,
    /// Override Hermes home directory. Defaults to HERMES_HOME or ~/.hermes.
    #[arg(long = "hermes-home")]
    hermes_home: Option<PathBuf>,
    /// Read this state.db instead of resolving one from --profile.
    #[arg(long = "db")]
    db_path: Option<PathBuf>,
    /// Ingest a Hermes CLI JSONL export instead of state.db.
    #[arg(long = "export-jsonl")]
    export_jsonl: Option<PathBuf>,
    /// Restrict ingest to one Hermes session id.
    #[arg(long = "session-id", alias = "session")]
    session_id: Option<String>,
    /// Restrict/tag ingest to this cwd. Defaults to source metadata when omitted.
    #[arg(long)]
    cwd: Option<PathBuf>,
    /// Print result as JSON.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Clone, Args)]
struct HermesQueryArgs {
    /// Search query string.
    query: Option<String>,
    /// Search query string, useful for `mempal recall hermes --query ...`.
    #[arg(long = "query")]
    query_flag: Option<String>,
    /// Hermes profile name.
    #[arg(long, default_value = "default")]
    profile: String,
    /// Restrict recall to this cwd. Defaults to the process cwd.
    #[arg(long)]
    cwd: Option<PathBuf>,
    /// Disable the default cwd filter.
    #[arg(long = "all-cwd")]
    all_cwd: bool,
    /// Restrict recall to one Hermes session id.
    #[arg(long = "session-id", alias = "session")]
    session_id: Option<String>,
    /// Restrict recall to a Hermes session source such as cli or telegram.
    #[arg(long = "session-source")]
    session_source: Option<String>,
    /// Restrict recall to an exact Hermes session title.
    #[arg(long = "session-title")]
    session_title: Option<String>,
    /// Prefer the newest matching session when no session id is supplied.
    #[arg(long)]
    latest: bool,
    /// Only return turns newer than this duration (e.g. 7d, 24h, 10m).
    #[arg(long)]
    since: Option<String>,
    /// Only return turns older than this duration window endpoint.
    #[arg(long)]
    until: Option<String>,
    /// Maximum number of results to return.
    #[arg(long, default_value_t = 10)]
    limit: usize,
    /// Page number (0-based).
    #[arg(long, default_value_t = 0)]
    page: usize,
    /// Also include CSA-delegated turns.
    #[arg(long)]
    include_csa: bool,
    /// Also include agent-generated user prompts.
    #[arg(long)]
    include_agent_prompts: bool,
    /// Minimum cosine similarity score (0.0-1.0).
    #[arg(long, default_value_t = 0.70)]
    min_score: f32,
    /// Output format: markdown (default) or json.
    #[arg(long, value_enum, default_value_t = XurlFormat::Markdown)]
    format: XurlFormat,
}

#[derive(Serialize)]
struct XurlStatsJson {
    tools: Vec<XurlStatsToolJson>,
    unindexed_remaining: i64,
}

#[derive(Serialize)]
struct XurlStatsToolJson {
    tool: String,
    count: i64,
    first: String,
    last: String,
    min_timestamp: f64,
    max_timestamp: f64,
}

impl From<XurlTool> for mempal::xurl::model::Tool {
    fn from(t: XurlTool) -> Self {
        match t {
            XurlTool::Cc => mempal::xurl::model::Tool::Cc,
            XurlTool::Codex => mempal::xurl::model::Tool::Codex,
            XurlTool::Hermes => mempal::xurl::model::Tool::Hermes,
        }
    }
}

