#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum HistoricalRejudgeStageMode {
    Paired,
    ProposalOnly,
    ConfirmPendingOnly,
}

impl HistoricalRejudgeStageMode {
    fn as_str(self) -> &'static str {
        match self {
            Self::Paired => "paired",
            Self::ProposalOnly => "proposal_only",
            Self::ConfirmPendingOnly => "confirm_pending_only",
        }
    }

    fn may_mutate(self) -> bool {
        !matches!(self, Self::ProposalOnly)
    }
}

#[derive(Clone, Copy)]
struct HistoricalRejudgeRuntimeOptions {
    llm_concurrency: usize,
    max_confirmations: Option<usize>,
}

impl Default for HistoricalRejudgeRuntimeOptions {
    fn default() -> Self {
        Self {
            llm_concurrency: DEFAULT_HISTORICAL_REJUDGE_LLM_CONCURRENCY,
            max_confirmations: None,
        }
    }
}

