    fn assert_historical_rejudge_startup_retry(name: &str, command: Commands) {
        assert!(
            command_retries_historical_rejudge_startup_open(&command),
            "expected startup retry for {name}"
        );
    }

    #[test]
    fn historical_rejudge_startup_retry_covers_top_level_sweep_modes() {
        assert_historical_rejudge_startup_retry(
            "limited dry-run",
            top_level_rejudge_command(|args| {
                args.limit = 20;
                args.format = "json".to_string();
            }),
        );
        assert_historical_rejudge_startup_retry(
            "all dry-run",
            top_level_rejudge_command(|args| {
                args.all = true;
            }),
        );
        assert_historical_rejudge_startup_retry(
            "execute",
            top_level_rejudge_command(|args| {
                args.execute = true;
                args.backup_dir = Some(PathBuf::from("/tmp/mempal-rejudge-backup"));
            }),
        );
        assert_historical_rejudge_startup_retry(
            "proposal-only",
            top_level_rejudge_command(|args| {
                args.all = true;
                args.proposal_only = true;
            }),
        );
        assert_historical_rejudge_startup_retry(
            "confirm-pending resume",
            top_level_rejudge_command(|args| {
                args.all = true;
                args.resume = true;
                args.execute = true;
                args.confirm_pending_only = true;
                args.backup_dir = Some(PathBuf::from("/tmp/mempal-rejudge-backup"));
            }),
        );
        assert_historical_rejudge_startup_retry(
            "resume",
            top_level_rejudge_command(|args| {
                args.all = true;
                args.resume = true;
                args.execute = true;
                args.backup_dir = Some(PathBuf::from("/tmp/mempal-rejudge-backup"));
            }),
        );
    }

    #[test]
    fn historical_rejudge_restore_subcommand_does_not_use_sweep_startup_retry() {
        let command = top_level_rejudge_command(|args| {
            args.command = Some(MaintenanceRejudgeCommands::Restore {
                backup: PathBuf::from("/tmp/mempal-rejudge-backup.json"),
                execute: false,
                conflict_policy: RejudgeRestoreConflictPolicy::Skip,
                format: "plain".to_string(),
            });
        });

        assert!(!command_retries_historical_rejudge_startup_open(&command));
    }

    #[test]
    fn historical_rejudge_startup_database_open_retries_transient_sqlite_lock() {
        let tmp = tempfile::TempDir::new().expect("tempdir");
        let db_path = tmp.path().join("palace.db");
        let attempts = std::cell::Cell::new(0);

        let db = open_historical_rejudge_startup_database_with_retry(|| {
            let current_attempt = attempts.get();
            attempts.set(current_attempt + 1);
            if current_attempt == 0 {
                Err(database_locked_open_error())
            } else {
                Database::open(&db_path).context("failed to open database")
            }
        })
        .expect("historical rejudge startup open must retry transient SQLite locks");

        assert_eq!(attempts.get(), 2);
        let drawer_count: i64 = db
            .conn()
            .query_row("SELECT COUNT(*) FROM drawers", [], |row| row.get(0))
            .expect("query opened database");
        assert_eq!(drawer_count, 0);
    }

    #[test]
    fn historical_rejudge_startup_database_open_does_not_retry_non_lock_sqlite_error() {
        let attempts = std::cell::Cell::new(0);

        let error = match open_historical_rejudge_startup_database_with_retry(|| {
            attempts.set(attempts.get() + 1);
            Err(anyhow::Error::new(rusqlite::Error::InvalidQuery)
                .context("failed to open database"))
        }) {
            Ok(_) => panic!("non-lock SQLite errors must remain fatal"),
            Err(error) => error,
        };

        assert_eq!(attempts.get(), 1);
        assert!(!is_transient_sqlite_lock_error(&error));
    }

    fn llm_rejudge_config(base_url: &str) -> Config {
        Config::parse(&format!(
            r#"
[llm]
enabled = true
base_url = "{base_url}/v1"
model = "test-judge"
request_timeout_secs = 1
retry_interval_secs = 1
enabled_for = ["gating"]

[gating]
enabled = true

[gating.llm_judge]
enabled = true
threshold = 0.3
"#
        ))
        .expect("parse llm rejudge config")
    }

