    #[test]
    fn historical_rejudge_confirm_pending_retries_transient_sqlite_lock() {
        let tmp = tempfile::TempDir::new().expect("tempdir");
        let db_path = tmp.path().join("palace.db");
        let db = Database::open(&db_path).expect("open db");
        ensure_historical_rejudge_checkpoint_storage(&db).expect("ensure checkpoint storage");
        let run_id = "retry-confirm-stage-run";
        db.conn()
            .execute(
                &format!(
                    r#"
                    INSERT INTO {HISTORICAL_REJUDGE_WORK_TABLE} (
                        run_id,
                        drawer_rowid,
                        drawer_id,
                        snapshot_content_hash,
                        snapshot_added_at,
                        snapshot_wing,
                        snapshot_source_type,
                        snapshot_normalize_version
                    ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)
                    "#
                ),
                rusqlite::params![
                    run_id,
                    7_i64,
                    "drawer-7",
                    "hash-7",
                    "2026-01-01T00:00:00Z",
                    "notes",
                    "agent_inference",
                    0_i64,
                ],
            )
            .expect("insert pending work item");
        db.conn()
            .busy_timeout(std::time::Duration::ZERO)
            .expect("make confirm-stage writer fail fast so retry behavior is observable");
        let blocker = rusqlite::Connection::open(&db_path).expect("open blocking connection");
        blocker
            .busy_timeout(std::time::Duration::ZERO)
            .expect("make blocker fail fast");
        blocker
            .execute_batch("BEGIN IMMEDIATE;")
            .expect("hold write lock");
        let release = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(75));
            blocker
                .execute_batch("COMMIT;")
                .expect("release write lock");
        });

        let result = mark_historical_rejudge_work_item_llm_confirm_pending(&db, run_id, 7, 0.125);
        release.join().expect("release thread");
        result.expect("confirm-pending stage write must retry a transient SQLite lock");

        let (stage, score): (String, f64) = db
            .conn()
            .query_row(
                &format!(
                    "SELECT llm_stage, llm_proposal_score FROM {HISTORICAL_REJUDGE_WORK_TABLE} WHERE run_id = ?1 AND drawer_rowid = ?2"
                ),
                rusqlite::params![run_id, 7_i64],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("load updated work item");
        assert_eq!(stage, "confirm_pending");
        assert_eq!(score, 0.125);
    }

    #[test]
    fn historical_rejudge_confirm_pending_exhausted_sqlite_lock_keeps_fail_closed() {
        let lock_error = rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error {
                code: rusqlite::ErrorCode::DatabaseLocked,
                extended_code: rusqlite::ffi::SQLITE_LOCKED,
            },
            Some("database is locked".to_string()),
        );

        let outcome = historical_rejudge_confirm_pending_persistence_outcome(
            Err(anyhow::Error::new(lock_error)),
            0.125,
        )
        .expect("transient lock should convert to a fail-closed keep decision");

        let HistoricalRejudgeConfirmPendingPersistence::Keep(decision) = outcome else {
            panic!("exhausted transient lock must not report a persisted confirmation stage");
        };
        assert!(!decision.delete_candidate);
        assert!(!decision.protected);
        assert_eq!(
            decision.reason,
            "llm_confirm_pending_persistence_locked_keep"
        );
        assert_eq!(decision.label.as_deref(), Some("llm_judge"));
        assert_eq!(decision.score, Some(0.125));
        assert_eq!(decision.tier, 3);
        assert_eq!(decision.judge, "llm");
    }

    #[test]
    fn historical_rejudge_treats_sqlite_protocol_as_transient_lock() {
        let protocol_error = rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error {
                code: rusqlite::ErrorCode::FileLockingProtocolFailed,
                extended_code: rusqlite::ffi::SQLITE_PROTOCOL,
            },
            Some("Database lock protocol error".to_string()),
        );
        let error = anyhow::Error::new(mempal::core::db::DbError::from(protocol_error))
            .context("failed to load historical rejudge work item test-drawer");

        assert!(
            is_transient_sqlite_lock_error(&error),
            "historical rejudge page errors caused by SQLITE_PROTOCOL must defer/retry instead of failing the run: {error:#}"
        );
    }

